def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def is_pair(v):
        return isinstance(v, (list, tuple)) and len(v) == 2 and is_num(v[0]) and is_num(v[1])

    def to_pos(v):
        if is_pair(v):
            return [int(v[0]), int(v[1])]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def extract_positions(obj, keyhint=""):
        found = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                kh = (str(k).lower() if k is not None else "") + " " + keyhint
                if is_pair(v):
                    p = to_pos(v)
                    if p is not None:
                        found.append((kh, p))
                elif isinstance(v, (list, tuple)):
                    if len(v) > 0 and all(is_pair(x) for x in v):
                        for x in v:
                            p = to_pos(x)
                            if p is not None:
                                found.append((kh, p))
                    else:
                        found.extend(extract_positions(v, kh))
                elif isinstance(v, dict):
                    found.extend(extract_positions(v, kh))
        elif isinstance(obj, (list, tuple)):
            for x in obj:
                if isinstance(x, dict):
                    found.extend(extract_positions(x, keyhint))
                elif is_pair(x):
                    p = to_pos(x)
                    if p is not None:
                        found.append((keyhint, p))
                elif isinstance(x, (list, tuple)):
                    found.extend(extract_positions(x, keyhint))
        return found

    obs = observation if isinstance(observation, dict) else {}
    text = (str(obs.get("task", "")) + " " + str(obs.get("mode", "")) + " " + str(obs.get("type", ""))).lower()

    self_pos = None
    # Direct hints
    for k in ("self", "agent", "player", "me", "position", "pos", "loc", "location", "current_position"):
        v = obs.get(k)
        p = to_pos(v)
        if p is not None:
            self_pos = p
            break

    if self_pos is None:
        # Search nested structure for self-like positions
        all_pos = extract_positions(obs)
        for kh, p in all_pos:
            if any(s in kh for s in ("self", "agent", "player", "me", "you", "current", "my")):
                self_pos = p
                break

    if self_pos is None:
        # Fallback to first found position
        all_pos = extract_positions(obs)
        if all_pos:
            self_pos = all_pos[0][1]

    if self_pos is None:
        return [0, 0]

    # Gather candidate targets
    positions = extract_positions(obs)
    resources = []
    enemies = []
    allies = []
    territory = []
    goals = []
    hazards = []

    for kh, p in positions:
        if p == self_pos:
            continue
        if any(s in kh for s in ("resource", "food", "gem", "coin", "pickup", "item")):
            resources.append(p)
        elif any(s in kh for s in ("enemy", "opponent", "adversary", "ghost", "foe", "pursuer")):
            enemies.append(p)
        elif any(s in kh for s in ("ally", "friend", "teammate")):
            allies.append(p)
        elif any(s in kh for s in ("territory", "base", "home", "zone", "owned", "claim")):
            territory.append(p)
        elif any(s in kh for s in ("goal", "target", "objective", "exit", "capture")):
            goals.append(p)
        elif any(s in kh for s in ("hazard", "danger", "wall", "obstacle", "trap", "lava")):
            hazards.append(p)

    # Additional explicit lists
    for k in ("resources", "resource_positions", "food", "items", "targets", "goals", "enemies", "opponents", "hazards", "walls", "obstacles"):
        v = obs.get(k)
        if isinstance(v, (list, tuple)):
