                if p is not None and p != self_pos:
                    if "resource" in k or "food" in k or "item" in k:
                        resources.append(p)
                    elif "enemy" in k or "opponent" in k:
                        enemies.append(p)
                    elif "hazard" in k or "wall" in k or "obstacle" in k:
                        hazards.append(p)
                    else:
                        goals.append(p)

    # De-duplicate
    def uniq(lst):
        out = []
        seen = set()
        for p in lst:
            t = (p[0], p[1])
            if t not in seen:
                seen.add(t)
                out.append(p)
        return out

    resources = uniq(resources)
    enemies = uniq(enemies)
    allies = uniq(allies)
    territory = uniq(territory)
    goals = uniq(goals)
    hazards = uniq(hazards)

