    task_pursuit = ("pursuit" in text)
    task_evasion = ("evasion" in text)
    task_territory = ("territory" in text or "control" in text)

    candidates = [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1)]
    best = [0, 0]
    best_score = None

