            width = len(grid[0])

    cx, cy = self_pos

    for dx, dy in candidates:
        nx, ny = cx + dx, cy + dy
        score = 0.0

        # Stay within bounds if known
        if isinstance(width, int) and nx < 0 or isinstance(height, int) and ny < 0:
            score -= 50
        if isinstance(width, int) and nx >= width:
            score -= 50
        if isinstance(height, int) and ny >= height:
            score -= 50

        # Prefer not to stand on hazards
        for h in hazards:
            d = abs(nx - h[0]) + abs(ny - h[1])
            if d == 0:
                score -= 100
            else:
                score -= 2.0 / d

        # Task-driven attraction/repulsion
        if task_resource and resources:
            d = min(manhattan([nx, ny], r) for r in resources)
            score += 20 - d
        if task_pursuit and enemies:
            d = min(manhattan([nx, ny], e) for e in enemies)
            score += 18 - d
        if task_evasion and enemies:
            d = min(manhattan([nx, ny], e) for e in enemies)
            score += d * 2.0
        if task_territory:
            if territory:
                d = min(manhattan([nx, ny], t) for t in territory)
                score += 12 - d
            else:
                # mild center-seeking when no territory info
                score += -abs(nx - cx) * 0.1 - abs(ny - cy) * 0.1

        # Generic targets
        if goals:
            d = min(manhattan([nx, ny], g) for g in goals)
            score += 8 - d

        # Generic resource fallback
        if not task_evasion and resources:
            d = min(manhattan([nx, ny], r) for r in resources)
            score += 6 - d

        # In pursuit mode, closing on enemies is good; in evasion mode bad
        if enemies and not task_evasion:
            d = min(manhattan([nx, ny], e) for e in enemies)
            score += 2 - 0.5 * d
        if enemies and task_evasion:
            d = min(manhattan([nx, ny], e) for e in enemies)
            score += 0.5 * d

        # Prefer moving over idling slightly
        if dx != 0 or dy != 0:
            score += 0.05

        # Small tie-breaker toward reducing lexicographic drift
        score += (dx * 0.001) + (dy * 0.0001)

        if best_score is None or score > best_score:
            best_score = score
            best = [dx, dy]

    return clamp_move(best[0], best[1])

